def prf(y_true, y_pred, positive='complaint'):
    tp = sum(1 for t, p in zip(y_true, y_pred) if t == p == positive)
    fp = sum(1 for t, p in zip(y_true, y_pred) if p == positive and t != positive)
    fn = sum(1 for t, p in zip(y_true, y_pred) if t == positive and p != positive)
    precision = tp / (tp + fp)
    recall = tp / (tp + fn)
    f1 = 2 * precision * recall / (precision + recall)
    return {'tp': tp, 'fp': fp, 'fn': fn, 'precision': round(precision, 4),
            'recall': round(recall, 4), 'f1': round(f1, 4)}

